import type { Metadata } from "next";
import { notFound } from "next/navigation";
import { getTranslations } from "next-intl/server";
import { isLocale, locales, ogLocales, type Locale } from "@/i18n/locales";
import { alternates, localizedUrl, siteName } from "./site";

/** Social sharing image (1200×630): the full emblem on cream, generated by `npm run assets`. */
const socialImage = { url: "/brand/og-image.png", width: 1200, height: 630, alt: "Gethsemane — Olive Wood · Holy Land" };

/** Title, description, canonical URL, hreflang alternates and Open Graph for a localized page. */
export async function pageMetadata({
  locale,
  path,
  title,
  description,
  noindex = false,
  image = socialImage,
  ogType = "website",
  canonical = false,
}: {
  locale: Locale;
  path: string;
  title?: string;
  description?: string;
  noindex?: boolean;
  /** Social sharing image; defaults to the brand image (products pass their own photo). */
  image?: { url: string; width: number; height: number; alt: string };
  /** null leaves og:type to the page (product pages render og:type "product" themselves). */
  ogType?: "website" | null;
  /** With noindex: still point search engines to the unfiltered page (e.g. filtered shop URLs → /shop). */
  canonical?: boolean;
}): Promise<Metadata> {
  // A malformed locale segment (e.g. /x.y/product/...) is a 404, never an error.
  if (!isLocale(locale)) notFound();
  const t = await getTranslations({ locale, namespace: "meta" });
  const desc = description ?? t("description");
  const fullTitle = title ? `${title} · ${siteName}` : t("title");
  return {
    title: { absolute: fullTitle },
    description: desc,
    alternates: noindex ? (canonical ? { canonical: localizedUrl(locale, path) } : undefined) : alternates(locale, path),
    robots: noindex ? { index: false, follow: true } : undefined,
    openGraph: {
      ...(ogType ? { type: ogType } : {}),
      siteName,
      title: fullTitle,
      description: desc,
      url: localizedUrl(locale, path),
      locale: ogLocales[locale],
      alternateLocale: locales.filter((l) => l !== locale).map((l) => ogLocales[l]),
      images: [image],
    },
    twitter: { card: "summary_large_image", title: fullTitle, description: desc, images: [image.url] },
  };
}
